function AddNewFileOrther() {
    var app = getParameterByName("App");
    var chkList = jQuery("#ShowtxtBox_File .checklength").length;
    var setData = "";
    if (chkList == 0) {
        var filesOrther = document.getElementById("file_other_0").files;
        var CheckFileType = [
            "image/png",
            "image/jpg",
            "image/jpeg",
            "application/pdf",
        ];
        var CheckFileType_img = ["image/png", "image/jpg", "image/jpeg"];
        var maxSizeMB = important_data.file_size;

        if (filesOrther.length > 0) {
            if (!CheckFileType.includes(filesOrther[0].type)) {
                Swal.fire({
                    imageUrl: important_data.warningIconUrl,
                    title: `<span class="lang_invalid_file_type">ชนิดของไฟล์ไม่ถูกต้อง</span>`,
                    type: "success",
                    confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
                }).then((result) => {
                    /* Read more about isConfirmed, isDenied below */
                    if (result.isConfirmed) {
                        OncOpenModalAddFile();
                    }
                });
                changeDatalang();
                return false;
            }
            var fileSizeMB = filesOrther[0].size / (1024 * 1024); // Convert bytes to MB
            if (fileSizeMB > maxSizeMB) {
                OncOpenModalAddFile();
                Swal.fire({
                    imageUrl: important_data.warningIconUrl,
                    title: `<span class="lang_file_size_exceeded">ขนาดของไฟล์เกิน</span>`,
                    type: "error",
                    confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
                }).then((result) => {
                    /* Read more about isConfirmed, isDenied below */
                    if (result.isConfirmed) {
                        OncOpenModalAddFile();
                    }
                });
                changeDatalang();
                return false;
            }
            var specialFilenameChars = /["\\/:*?<>|,]/;
            if (specialFilenameChars.test(filesOrther[0].name)) {
                Swal.fire({
                    imageUrl: important_data.warningIconUrl,
                    title: `<span class="lang_Invalid_file_name">ชื่อไฟล์ไม่ถูกต้อง</span>`,
                    html: `<span class="lang_invalid_characters">ชื่อไฟล์มีอักขระที่ไม่ถูกต้อง</span> <span>(\\/:*?&lt;&gt;|,)</span>`,
                    confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
                }).then((result) => {
                    /* Read more about isConfirmed, isDenied below */
                    if (result.isConfirmed) {
                        OncOpenModalAddFile();
                    }
                });
                changeDatalang();
                return false;
            }

            var reader = new FileReader();

            reader.readAsDataURL(filesOrther[0]);
            reader.onload = function () {
                let base64 = reader.result;
                var fileUpload = filesOrther[0];
                var objectUrl = URL.createObjectURL(fileUpload);
                var span = $("#show_file_name_orther0");

                if (CheckFileType_img.includes(filesOrther[0].type)) {
                    handleFileUpload(fileUpload, null)
                        .then((filecrop) => {
                            if (filecrop) {
                                let dataTransfer = new DataTransfer();
                                dataTransfer.items.add(filecrop);
                                let fileList = dataTransfer.files;

                                if (app == "Y" || app == "y") {
                                    span.wrap(
                                        '<a onclick="sendmessage(&quot;' + base64 + '&quot;)"></a>'
                                    );
                                    FileOrtherbase64 = base64;
                                } else {
                                    span.wrap('<a href="' + objectUrl + '" target="_blank"></a>');
                                    objectUrllink = objectUrl;
                                }

                                $("#divshow_file_name_orther").css("display", "flex");
                                $("#show_file_name_orther0").text(fileUpload.name);
                                /*$("#div_show_upload").css('display', 'none');*/
                                $("#hidden_file_name_orther").val(fileUpload.name);
                                $("#hidden_file_up_0").prop("files", fileList);
                                $("#file_name_select_0").val(fileUpload.name);
                                $("#text_file_name_00").val(fileUpload.name);
                            }
                        })
                        .catch((error) => {
                            console.error(error);
                        });
                } else {
                    if (fileUpload != undefined) {
                        if (app == "Y" || app == "y") {
                            span.wrap(
                                '<a onclick="sendmessage(&quot;' + base64 + '&quot;)"></a>'
                            );
                            FileOrtherbase64 = base64;
                        } else {
                            span.wrap('<a href="' + objectUrl + '" target="_blank"></a>');
                            objectUrllink = objectUrl;
                        }

                        $("#divshow_file_name_orther").css("display", "flex");
                        $("#show_file_name_orther0").text(fileUpload.name);
                        /*$("#div_show_upload").css('display', 'none');*/
                        $("#hidden_file_name_orther").val(fileUpload.name);
                        $("#hidden_file_up_0").prop("files", filesOrther);
                        $("#file_name_select_0").val(fileUpload.name);
                        $("#text_file_name_00").val(fileUpload.name);
                        $("#show_orther_file_name_0").text(fileUpload.name);
                    }
                }
            };
        }
